   const nextDay=next?(d=>d===0?'today':d===1?'tomorrow':formatDate(next.dueAt,c.s.timeZone,d<7?{weekday:'long'}:{weekday:'long',month:'short',day:'numeric'}))(daysFrom(dayKey(next.dueAt,c.s.timeZone))):'';
