  function reader(){const item=c.selected;if(item?.personal)return personalReader(item);if(!item)return '';const course=c.courseMap.get(String(item.courseId))||{},l=local[item.id]||{},content=c.readerContent||{html:'',links:[]},steps=(l.checklist||[]).length,link=assignmentLink(item),changed=updated(item.updatedAt),points=(item.rubric||[]).reduce((sum,r)=>sum+(Number(r.points)||0),0),planned=l.plannedDate===today;return `<aside data-rd-key="reader" class="rd-reader" data-id="${item.id}" aria-labelledby="rd-reader-title" style="${tone(course.color||'#69758b')}">${readerTop(course,item,detail(course)?`<small> · ${E(detail(course))}</small>`:'',link)}<div class="rd-reader-content" data-rd-key="reader-content"><h2 id="rd-reader-title" tabindex="-1">${E(item.name)}</h2><p class="rd-reader-facts"><span data-tone="${dueTone(item)}">${E(dueLong(item))}</span>${Number.isFinite(item.points)?`<span>${c.s.showGrades===true&&item.score!==null&&Number.isFinite(item.score)?E(item.score)+' / ':''}${E(item.points)} points</span>`:''}${(status=>`<span data-tone="${stateTone(status)}">${E(status)}</span>`)(item.state==='excused'?'Excused':item.redoRequested?'Resubmission requested':item.missing?'Marked missing in Canvas':complete(item)?item.state==='graded'?'Graded':'Submitted':item.state==='unknown'?'Check submission in Canvas':'Not submitted')}</p><div class="rd-reader-actions"><a class="rd-button rd-button--primary" href="${E(link)}">${l.progress==='done'&&!complete(item)?online(item)?'Open Canvas to submit':'Check completion in Canvas':'Open in Canvas'} ${icon('external')}</a>${checkButton(item,true)}${bookmarkButton(item,true)}${action('schedule',icon(planned?'check':'plus')+(planned?'In today’s plan':'Plan for today'),`data-id="${item.id}" data-day="${today}" aria-pressed="${planned}"`,'rd-button rd-plan-today')}</div><div class="rd-reader-sections"><div class="rd-reader-tabs" data-rd-key="reader-tabs" role="group" aria-label="Assignment preview sections">${action('reader-tab','Instructions',`data-tab="details" aria-pressed="${c.readerTab==='details'}"`,'rd-reader-tab')}${action('reader-tab',`My plan${steps?` <span class="rd-n">${steps} step${steps===1?'':'s'}</span>`:''}`,`data-tab="plan" aria-pressed="${c.readerTab==='plan'}"`,'rd-reader-tab')}</div>${changed?`<small>${E(changed)}</small>`:''}</div><div class="rd-reader-body" data-rd-key="reader-body">${c.readerTab==='plan'?plan(item):`${content.links.length?`<section class="rd-resources"><h3>Linked materials <span>${content.links.length}</span></h3>${content.links.map(link=>`<a href="${E(link.url)}" target="_blank" rel="noopener noreferrer">${icon('folder')}<span>${E(link.label)}</span>${icon('external')}</a>`).join('')}</section>`:''}<section class="rd-instructions" aria-label="Teacher instructions"><div class="rd-rich-text">${content.html.trim()||(content.links.length?'<p>Open the linked material to continue.</p>':'<p>No instructions were included. Check the teacher’s course information or open the original.</p>')}</div></section>${item.rubric?.length?`<details class="rd-rubric" data-rd-section="rubric"><summary>${icon('chevron')}<span>Grading rubric</span><small> · ${item.rubric.length} criteri${item.rubric.length===1?'on':'a'}${points?` · ${E(points)} points`:''}</small></summary>${item.rubric.map(r=>`<div><strong>${E(r.description)}</strong><span>${E(r.points??'—')} pts</span><p>${E(r.long_description||'')}</p></div>`).join('')}</details>`:''}`}</div></div></aside>`;}
  function grades(){return `<section class="rd-grades" data-rd-key="recent-grades" aria-label="Recent scored work"><div class="rd-section-heading"><h2>Recent scored work</h2>${action('grades','All grades '+icon('arrow'),'','rd-text-button')}</div><div class="rd-grade-results">${insights.recentGrades.map(item=>`<a href="${E(assignmentLink(item))}" class="rd-grade-result"><span>${unbreak(E(short(c.courseMap.get(String(item.courseId)))||item.courseName))}</span><strong>${E(item.name)}</strong><b>${E(item.score)}${Number.isFinite(item.points)?` <small>/ ${E(item.points)}</small>`:''}</b></a>`).join('')||'<p class="rd-muted">Scored assignments will appear when Canvas returns them.</p>'}</div></section>`;}
  const alerts=insights.ready.length?`<div class="rd-ready-note" data-rd-key="ready">${icon('upload')}<span>${insights.ready.length} assignment${insights.ready.length===1?' is':'s are'} done in your plan; completion still needs to be checked.</span>${action('view','Review',`data-mode="ready"`,'rd-text-button')}</div>`:'';
